package com.rinsing.realmfolk.design;

import com.google.gson.JsonParser;
import com.rinsing.realmfolk.model.Society;
import org.junit.jupiter.api.Test;
import java.util.*;
import static com.rinsing.realmfolk.model.Society.*;
import static org.junit.jupiter.api.Assertions.*;

class DesignTest {
    private static final Set<String> ITEMS=Set.of("minecraft:air","minecraft:iron_sword","minecraft:bread","minecraft:oak_log","minecraft:iron_ingot","minecraft:wheat");
    private static Design design(){
        Design d=DesignCodec.defaults();var s=d.realms.get("default").population;s.populationMode="fixed";s.population=6;s.residentsPerHouse=2;s.saleHouseEvery=0;
        s.jobs=new LinkedHashMap<>(Map.of("resident",new Design.Quota(0,6,2),"smith",new Design.Quota(1,2,1)));return d;
    }
    private static Society world(){
        Society s=new Society();s.design.active=design();s.design.revision=1;
        s.towns.put("town",new Town("town","realm","测试城",new Point(0,65,0)));
        for(int i=0;i<3;i++){Property p=new Property("house"+i,"town","民居",new Bounds(i*10,64,0,i*10+8,70,8),new Point(i*10+2,65,2));p.terms=List.of("住宅");p.slots=List.of(p.home,p.home.offset(2,0,0));s.properties.put(p.id,p);}
        Property work=new Property("work","town","工坊",new Bounds(0,64,20,8,70,28),new Point(2,65,22));work.terms=List.of("工坊生产");s.properties.put(work.id,work);return s;
    }
    private static PopulationPlanner.Plan plan(Society s){return PopulationPlanner.plan(s.design.active,s,s.towns.get("town"),17,1);}
    @Test void defaultsAreValid(){assertEquals(List.of(),new DesignValidator(ITEMS::contains).validate(DesignCodec.defaults()));}
    @Test void rejectsExecutableAndUnknownFields(){assertThrows(IllegalArgumentException.class,()->DesignCodec.decode(JsonParser.parseString("{\"professions\":{\"mage\":{\"script\":\"doStuff()\"}}}"),Design.Patch.class));}
    @Test void rejectsCoercedTypesAndNulls(){for(String text:List.of("{\"version\":\"2\"}","{\"version\":2.5}","{\"realms\":null}"))assertThrows(IllegalArgumentException.class,()->DesignCodec.decode(JsonParser.parseString(text),Design.class));}
    @Test void rejectsUnknownAbilitiesAndUnsafeCombos(){Design d=design();d.professions.get("resident").capabilities.add("execute_script");assertFalse(new DesignValidator(ITEMS::contains).validate(d).isEmpty());d=design();d.professions.get("guard").capabilities.add("companion");assertFalse(new DesignValidator(ITEMS::contains).validate(d).isEmpty());}
    @Test void rejectsUnknownItems(){Design d=design();d.professions.get("smith").offers.get(0).item="absent:thing";assertFalse(new DesignValidator(ITEMS::contains).validate(d).isEmpty());}
    @Test void arbitraryProfessionNamesComposeCapabilities(){Society s=world();var d=s.design.active;var miner=DesignCodec.copy(d.professions.get("smith"),Design.Profession.class);miner.name="崖京矿材商";d.professions.put("yajing_miner",miner);d.realms.get("default").population.jobs=Map.of("yajing_miner",new Design.Quota(1,6,1));assertTrue(new DesignValidator(ITEMS::contains).validate(d).isEmpty());var p=plan(s);assertEquals(4,p.citizens().size());assertTrue(p.citizens().stream().allMatch(c->c.profession.name.equals("崖京矿材商")&&c.profession.has("trade")));}
    @Test void cityOverridesRealmAndTemplate(){Design d=design();var realm=new Design.RealmRule();realm.population.names=List.of("国度名");d.realms.put("mining",realm);d.realmBindings.put("realm","mining");var template=new Design.Settings();template.population=12;d.cityTemplates.put("mine",template);var city=new Design.CityPlan();city.template="mine";city.overrides.population=8;d.cities.put("town",city);var resolved=d.resolve("realm","town");assertEquals(8,resolved.settings().population);assertEquals(List.of("国度名"),resolved.settings().names);assertEquals(2,resolved.settings().residentsPerHouse);}
    @Test void deterministicDespitePropertyMapOrder(){Society s=world();var first=plan(s);List<Property> reverse=new ArrayList<>(s.properties.values());Collections.reverse(reverse);s.properties.clear();reverse.forEach(p->s.properties.put(p.id,p));assertEquals(DesignCodec.JSON.toJson(first),DesignCodec.JSON.toJson(plan(s)));}
    @Test void assignsDistinctHomesAndSeparateWorkplaces(){var p=plan(world());assertEquals(6,p.citizens().size());assertEquals(6,p.citizens().stream().map(c->c.home).distinct().count());var smith=p.citizens().stream().filter(c->c.role.equals("smith")).findFirst().orElseThrow();assertNotEquals(smith.property,smith.workProperty);assertNotEquals(smith.home,smith.work);}
    @Test void respectsWorkplaceCapacityAndJobMaximum(){Society s=world();var settings=s.design.active.realms.get("default").population;settings.jobs=Map.of("smith",new Design.Quota(0,6,1));settings.workplaceCapacity=1;assertEquals(1,plan(s).citizens().size());settings.workplaceCapacity=6;settings.jobs.get("smith").max=2;assertEquals(2,plan(s).citizens().size());}
    @Test void missingWorkplaceReservesMinimumInsteadOfFillingWithResidents(){Society s=world();s.properties.remove("work");var p=plan(s);assertEquals(5,p.citizens().size());assertTrue(p.summary().shortages().stream().anyMatch(x->x.contains("smith")));}
    @Test void forSaleAndPlayerHomesAreExcluded(){Society s=world();s.properties.get("house0").price=32;s.properties.get("house1").owner="player:alice";assertEquals(2,plan(s).citizens().size());}
    @Test void keepsExistingIdentityAndDoesNotResurrect(){Society s=world();var first=plan(s);first.citizens().forEach(c->s.citizens.put(c.id,c));s.citizens.values().iterator().next().dead=true;assertEquals(0,plan(s).citizens().size());assertEquals(6,s.citizens.size());}
    @Test void keyPeopleAreGeneratedOnceBeforeFillers(){Society s=world();var city=new Design.CityPlan();var key=new Design.KeyPerson();key.id="master";key.name="岩师";key.profession="smith";city.keyPeople.add(key);s.design.active.cities.put("town",city);var result=plan(s);assertTrue(result.citizens().get(0).keyPerson);assertEquals("岩师",result.citizens().get(0).name);result.citizens().forEach(c->s.citizens.put(c.id,c));assertEquals(0,plan(s).citizens().size());}
    @Test void previewAndPublicationAgreeAndRetriesAreIdempotent(){Society s=world();var tx=new DesignTransactions(s,17,ITEMS::contains);var draft=tx.submit(1,new Design.Patch(),List.of("town"),"future_only");var preview=tx.preview(draft.id);assertEquals(6,preview.towns().get(0).created());assertEquals(0,s.citizens.size());var result=tx.publish(draft.id,preview.previewToken());assertEquals(6,result.created());assertEquals(result,tx.publish(draft.id,preview.previewToken()));assertEquals(6,s.citizens.size());}
    @Test void stateChangesRequireAnotherPreview(){Society s=world();var tx=new DesignTransactions(s,17,ITEMS::contains);var draft=tx.submit(1,new Design.Patch(),List.of("town"),"future_only");var preview=tx.preview(draft.id);s.properties.get("house0").owner="player:alice";assertThrows(IllegalArgumentException.class,()->tx.publish(draft.id,preview.previewToken()));assertEquals(1,s.design.revision);assertEquals(0,s.citizens.size());assertEquals(4,tx.publish(draft.id,tx.preview(draft.id).previewToken()).created());}
    @Test void conflictingDraftCannotOverwriteNewRevision(){Society s=world();var tx=new DesignTransactions(s,17,ITEMS::contains);var a=tx.submit(1,new Design.Patch(),List.of("town"),"future_only");var b=tx.submit(1,new Design.Patch(),List.of("town"),"future_only");tx.publish(a.id,tx.preview(a.id).previewToken());assertThrows(IllegalArgumentException.class,()->tx.preview(b.id));}
    @Test void explicitRefreshProtectsRelationshipsAndRolledAttributes(){Society s=world();plan(s).citizens().forEach(c->s.citizens.put(c.id,c));var citizens=new ArrayList<>(s.citizens.values());citizens.get(0).keyPerson=true;citizens.get(1).leader="alice";s.journal("alice").like(citizens.get(2).id,1);s.journal("alice").quests.put("supply:"+citizens.get(3).id,"ACTIVE");var patch=new Design.Patch();var resident=DesignCodec.copy(s.design.active.professions.get("resident"),Design.Profession.class);resident.name="新称谓";patch.professions.put("resident",resident);var tx=new DesignTransactions(s,17,ITEMS::contains);var draft=tx.submit(1,patch,List.of("town"),"refresh_unprotected");var preview=tx.preview(draft.id);assertEquals(4,preview.protectedCitizens());assertEquals(2,preview.refreshable());tx.publish(draft.id,preview.previewToken());for(int i=0;i<4;i++)assertSame(citizens.get(i),s.citizens.get(citizens.get(i).id));for(var c:citizens){assertEquals(c.health,s.citizens.get(c.id).health);assertEquals(c.home,s.citizens.get(c.id).home);}}
    @Test void futureOnlyKeepsAllExistingSnapshots(){Society s=world();plan(s).citizens().forEach(c->s.citizens.put(c.id,c));String before=DesignCodec.hash(s.citizens);var patch=new Design.Patch();var job=DesignCodec.copy(s.design.active.professions.get("resident"),Design.Profession.class);job.name="新职业名";patch.professions.put("resident",job);var tx=new DesignTransactions(s,17,ITEMS::contains);var draft=tx.submit(1,patch,List.of("town"),"future_only");tx.publish(draft.id,tx.preview(draft.id).previewToken());assertEquals(before,DesignCodec.hash(s.citizens));}
    @Test void globalChangesMustPreviewEveryAffectedCity(){Society s=world();s.towns.put("another",new Town("another","realm","另一座城",new Point(100,65,0)));var patch=new Design.Patch();var template=new Design.Settings();template.population=8;patch.cityTemplates.put("default",template);var tx=new DesignTransactions(s,17,ITEMS::contains);assertThrows(IllegalArgumentException.class,()->tx.submit(1,patch,List.of("town"),"future_only"));assertTrue(s.design.drafts.isEmpty());}
    @Test void draftsAndProfilesSurviveJsonRoundTrip(){Society s=world();plan(s).citizens().forEach(c->s.citizens.put(c.id,c));var tx=new DesignTransactions(s,17,ITEMS::contains);var draft=tx.submit(1,new Design.Patch(),List.of("town"),"future_only");String token=tx.preview(draft.id).previewToken();Society loaded=DesignCodec.copy(s,Society.class);assertEquals(token,new DesignTransactions(loaded,17,ITEMS::contains).preview(draft.id).previewToken());assertEquals(DesignCodec.hash(s.citizens),DesignCodec.hash(loaded.citizens));}
}
